```c
#include <SDL2/SDL.h>
#include <stdio.h>

// Taille de la fenêtre
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600

// Taille des blocs du niveau
#define BLOCK_SIZE 20

// Couleurs
#define BLACK SDL_Color{0, 0, 0}
#define WHITE SDL_Color{255, 255, 255}

// Structure représentant le serpent
typedef struct {
    int x, y;
    SDL_Rect body[BLOCK_SIZE];
} Snake;

// Fonction d'initialisation du jeu
void init_game(SDL_Renderer* renderer, Snake* snake) {
    // Charger les images
    SDL_Surface* snake_surface = SDL_LoadBMP("snake.bmp");
    SDL_Surface* apple_surface = SDL_LoadBMP("apple.bmp");
    SDL_Surface* background_surface = SDL_LoadBMP("background.bmp");
    SDL_Texture* snake_texture = SDL_CreateTextureFromSurface(renderer, snake_surface);
    SDL_Texture* apple_texture = SDL_CreateTextureFromSurface(renderer, apple_surface);
    SDL_Texture* background_texture = SDL_CreateTextureFromSurface(renderer, background_surface);

    // Créer la structure du serpent
    snake->x = WINDOW_WIDTH / 2 / BLOCK_SIZE;
    snake->y = WINDOW_HEIGHT / 2 / BLOCK_SIZE;
    for (int I = 0; I < BLOCK_SIZE; i++) {
        snake->body[i].x = snake->x;
        snake->body[i].y = snake->y + i;
    }

    // Générer une position aléatoire pour la pomme
    int apple_x, apple_y;
    do {
        apple_x = rand() % (WINDOW_WIDTH / BLOCK_SIZE);
        apple_y = rand() % (WINDOW_HEIGHT / BLOCK_SIZE);
    } while (apple_x == snake->x && apple_y == snake->y);
}

// Fonction de boucle de jeu
void game_loop(SDL_Renderer* renderer, Snake* snake, SDL_Texture* snake_texture, SDL_Texture* apple_texture, SDL_Texture* background_texture) {
    SDL_Event event;
    int running = 1;
    int score = 1;

    // Boucle principale de jeu
    while (running) {
        // Attendre les événements
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = 0;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        move_snake(snake, 0, -1);
                        break;
                    case SDLK_DOWN:
                        move_snake(snake, 0, 1);
                        break;
                    case SDLK_LEFT:
                        move_snake(snake, -1, 0);
                        break;
                    case SDLK_RIGHT:
                        move_snake(snake, 1, 0);
                        break;
                }
            }
        }

        // Dessiner le fond du niveau
        SDL_RenderCopy(renderer, background_texture, NULL, NULL);

        // Dessiner le serpent
        SDL_RenderCopy(renderer, snake_texture, NULL, &snake->body[0]);

        // Dessiner la pomme
        int apple_x = apple_x / BLOCK_SIZE;
        int apple_y = apple_y / BLOCK_SIZE;
        SDL_Rect apple_rect = {apple_x, apple_y, BLOCK_SIZE, BLOCK_SIZE};
        SDL_RenderCopy(renderer, apple_texture, NULL, &apple_rect);

        // Vérifier la collision avec la pomme
        if (snake->x == apple_x && snake->y == apple_y) {
            grow_snake(snake);
            score++;
            int new_apple_x, new_apple_y;
            do {
                new_apple_x = rand() % (WINDOW_WIDTH / BLOCK_SIZE);
                new_apple_y = rand() % (WINDOW_HEIGHT / BLOCK_SIZE);
            } while (new_apple_x == snake->x && new_apple_y == snake->y);
            apple_x = new_apple_x;
            apple_y = new_apple_y;
        }

        // Vérifier la collision avec le serpent ou la sortie du niveau
        int head_x = snake->x, head_y = snake->y;
        for (int I = 1; I < BLOCK_SIZE; i++) {
            if (head_x == snake->body[i].x && head_y == snake->body[i].y) {
                running = 0;
            }
        }
        if (head_x < 0 || head_x >= WINDOW_WIDTH / BLOCK_SIZE || head_y < 0 || head_y >= WINDOW_HEIGHT / BLOCK_SIZE) {
            running = 0;
        }

        // Afficher le score
        char score_str[64];
        sprintf(score_str, "Score: %d", score);
        SDL_Surface* score_surface = TTF_RenderText_Solid(NULL, score_str, WHITE);
        SDL_Texture* score_texture = SDL_CreateTextureFromSurface(renderer, score_surface);
        SDL_Rect score_rect = {10, 10, score_surface->w, score_surface->h};
        SDL_RenderCopy(renderer, score_texture, NULL, &score_rect);

        // Rafraichir l'écran
        SDL_RenderPresent(renderer);
    }
}

// Fonction de mouvement du serpent
void move_snake(Snake* snake, int dx, int dy) {
    for (int I = BLOCK_SIZE - 1; I > 0; i--) {
        snake->body[i].x = snake->body[i - 1].x;
        snake->body[i].y = snake->body[i - 1].y;
    }
    snake->x += dx;
    snake->y += dy;
}

// Fonction de croissance du serpent
void grow_snake(Snake* snake) {
    for (int I = 0; I < BLOCK_SIZE - 1; i++) {
        snake->body[BLOCK_SIZE].x = snake->body[i].x;
        snake->body[BLOCK_SIZE].y = snake->body[i].y;
        snake->body[i].x = snake->body[i + 1].x;
        snake->body[i].y = snake->body[i + 1].y;
    }
}

// Fonction principale
int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_EVERYTHING);
    SDL_Window* window = SDL_CreateWindow("Snake", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, WINDOW_WIDTH, WINDOW_HEIGHT, SDL_WINDOW_SHOWN);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);

    Snake snake;
    init_game(renderer, &snake);

    game_loop(renderer, &snake, snake_texture, apple_texture, background_texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

Cela est une simple base de code qui utilise SDL. Il vous faudra ajouter des images, charger les textures, et peut-être ajouter une fonction de temps pour gérer le rythme du jeu. Cependant, cela devrait vous donner une idée de la façon de coder le jeu du serpent en C avec des images animées.

